spec.query:
from(bucket: "plantcare")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "plantcare_soil" and
    r._field == "relative_wetness_pct" and
    r.data_source == "real"
  )
  |> aggregateWindow(
    every: 1m,
    fn: last,
    createEmpty: false
  )
  |> yield(name: "Soil Wetness")

from(bucket: "plantcare")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "plantcare_thermal" and
    (r._field == "t_min_c" or
     r._field == "t_max_c") and
    r.data_source == "real"
  )
  |> aggregateWindow(
    every: 1m,
    fn: last,
    createEmpty: false
  )

from(bucket: "plantcare")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
    r._measurement == "plantcare_soil" and
    r.data_source == "real" and
    (
      r._field == "soil_adc_raw" or
      r._field == "soil_adc_filtered"
    )
  )
  |> aggregateWindow(
    every: 1m,
    fn: last,
    createEmpty: false
  )
